const event = $json.body;
const text = (value, limit) => typeof value === 'string' && value.trim() && value.length <= limit ? value.trim() : null;
const eventId = text(event?.eventId, 120);
const reference = text(event?.delivery?.reference, 40);
const recipient = text(event?.delivery?.recipientName, 100);
const unit = text(event?.delivery?.unit, 40);
const description = text(event?.delivery?.description, 160);
const carrier = text(event?.delivery?.carrier, 80);
const attemptNumber = event?.attempt?.number;
if (event?.type !== 'delivery.notification.requested' || !eventId || !reference || !recipient || !unit || !description || !carrier || !Number.isInteger(attemptNumber) || attemptNumber < 1) {
  throw new Error('Evento de encomenda inválido.');
}
const greeting = `Olá, ${recipient}! Uma encomenda chegou à portaria do seu condomínio.`;
const messagePreview = `${greeting} Referência: ${reference}. Unidade: ${unit}. Procure a portaria para retirar.`;
return [{ json: { accepted: true, eventId, status: 'received', reference, attemptNumber, messagePreview } }];
